    for(int i=0;i<m;i++){int u,v,w;cin>>u>>v>>w;g[u].push_back({v,w});g[v].push_back({u,w});}
    const ll INF=1LL<<60;
    vector<ll>d(n+1,INF);
    priority_queue<pair<ll,int>,vector<pair<ll,int>>,greater<pair<ll,int>>>q;
    d[1]=0;q.push({0,1});
    while(!q.empty()){
        auto [du,u]=q.top();q.pop();
        if(du!=d[u])continue;
        if(u==n)break;
        for(auto [v,w]:g[u])if(d[v]>du+w+wait[v]){
            d[v]=du+w+wait[v];q.push({d[v],v});
        }
    }
    cout<<(d[n]==INF?-1:d[n])<<"\n";
}
```

### 易错点

终点不需要隔离，起点也不需要隔离。图是无向图，要插入两个方向。不能用普通 BFS 代替带权最短路；松弛时应加目标城市的等待时间。

